('Maximum Subarray', 'Given an integer array nums, find the subarray with the largest sum and return its sum (Kadane algorithm).', 'medium', 'def maxSubArray(nums):\n    # write your code here', '[{"input":"-2 1 -3 4 -1 2 1 -5 4","expected_output":"6"}]', '[{"input":"-2 1 -3 4 -1 2 1 -5 4","expected_output":"6"}]', '[{"input":"1","expected_output":"1"}]', 'Space-separated integers', 'Maximum subarray sum', '1 <= nums.length <= 10^5', '["array","divide-conquer","dynamic-programming"]', '["python","java","cpp","javascript"]', 15),
('Maximum Product Subarray', 'Given an integer array nums, find a subarray that has the largest product, and return the product.', 'medium', 'def maxProduct(nums):\n    # write your code here', '[{"input":"2 3 -2 4","expected_output":"6"}]', '[{"input":"2 3 -2 4","expected_output":"6"}]', '[{"input":"-2 0 -1","expected_output":"0"}]', 'Space-separated integers', 'Maximum product value', '1 <= nums.length <= 2 * 10^4', '["array","dynamic-programming"]', '["python","java","cpp","javascript"]', 15),
